{
  "scenario": "schelling",
  "phenomenon": "schelling segregation dynamics",
  "indicators": [
    {
      "id": "micro_mean_local_similarity",
      "semantic_name": "Mean local same-group fraction",
      "scientific_definition": "Average occupied-neighbour same-group fraction across all agents in the step.",
      "phenomenon": "segregation dynamics",
      "scale": "micro",
      "entity_scope": "individual",
      "entities": "agents",
      "source_fields": [
        "local_similarity"
      ],
      "computation": {
        "op": "mean",
        "input": {
          "op": "field",
          "name": "local_similarity"
        },
        "axis": "agent"
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "scientific_rationale": "Individual local similarity is the direct local social exposure driving dissatisfaction and subsequent relocation."
    },
    {
      "id": "micro_unhappy_fraction",
      "semantic_name": "Unhappy agent fraction",
      "scientific_definition": "Fraction of agents whose local same-group fraction is below the tolerance threshold.",
      "phenomenon": "segregation dynamics",
      "scale": "micro",
      "entity_scope": "elementary_event",
      "entities": "agents",
      "source_fields": [
        "unhappy"
      ],
      "computation": {
        "op": "fraction",
        "input": {
          "op": "field",
          "name": "unhappy"
        },
        "axis": "agent"
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [
        {
          "parameter": "tolerance",
          "relationship": "direct",
          "expected_indicator_direction": "increase",
          "rationale": "Higher tolerance raises the minimum required local similarity, making more agents unhappy."
        }
      ],
      "scientific_rationale": "Unhappy events capture the individual trigger state that precedes relocation attempts."
    },
    {
      "id": "micro_mean_neighbour_count",
      "semantic_name": "Mean occupied neighbour count",
      "scientific_definition": "Average number of occupied Moore neighbours per agent in the step.",
      "phenomenon": "segregation dynamics",
      "scale": "micro",
      "entity_scope": "individual",
      "entities": "agents",
      "source_fields": [
        "neighbour_count"
      ],
      "computation": {
        "op": "mean",
        "input": {
          "op": "field",
          "name": "neighbour_count"
        },
        "axis": "agent"
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "scientific_rationale": "Local occupancy shapes an agent's information context and the pool of possible same-group neighbours."
    },
    {
      "id": "micro_moved_fraction",
      "semantic_name": "Relocation event fraction",
      "scientific_definition": "Fraction of agents that relocated during the step.",
      "phenomenon": "segregation dynamics",
      "scale": "micro",
      "entity_scope": "elementary_event",
      "entities": "agents",
      "source_fields": [
        "moved"
      ],
      "computation": {
        "op": "fraction",
        "input": {
          "op": "field",
          "name": "moved"
        },
        "axis": "agent"
      },
      "temporal_aggregation": {
        "op": "identity",
        "window": null
      },
      "parameter_associations": [
        {
          "parameter": "move_probability",
          "relationship": "direct",
          "expected_indicator_direction": "increase",
          "rationale": "Higher move probability directly increases the chance that an unsatisfied agent attempts relocation."
        }
      ],
      "scientific_rationale": "Relocation events are the primary dynamic action that reorganizes the spatial configuration."
    },
    {
      "id": "micro_mean_move_distance",
      "semantic_name": "Mean relocation distance",
      "scientific_definition": "Average periodic Manhattan relocation distance over all agents in the step, with non-movers contributing zero.",
      "phenomenon": "segregation dynamics",
      "scale": "micro",
      "entity_scope": "individual",
      "entities": "agents",
      "source_fields": [
        "move_distance"
      ],
